+@page "/chat"
+@using sv_9d9428b8696845c494c017eacb11c935.Services
+@inject IChatService ChatService
+@rendermode InteractiveServer
+
+<PageTitle>Team Chat</PageTitle>
+
+<div class="chat-layout">
+    <ChannelSidebar Channels="channels"
+                    ActiveChannelId="selectedChannelId"
+                    OnChannelSelected="SelectChannel" />
+
+    <div class="chat-main @(threadOpen ? "thread-open" : "")">
+        <MessageArea ChannelName="@currentChannelName"
+                     ChannelDescription="@currentChannelDescription"
+                     Messages="messages"
+                     ThreadReplyCounts="threadReplyCounts"
+                     IsLoadingMore="isLoadingMore"
+                     OnOpenThread="OpenThread"
+                     OnReact="HandleReaction"
+                     OnLoadMore="LoadMoreMessages"
+                     OnSendMessage="SendMessage" />
+
+        @if (threadOpen)
+        {
+            <ThreadPanel RootMessage="threadRootMessage"
+                         Replies="threadReplies"
+                         OnReply="SendThreadReply"
+                         OnClose="CloseThread" />
+        }
+    </div>
+</div>
+
+@code {
+    private List<Channel> channels = [];
+    private List<Message> messages = [];
+    private Dictionary<int, int> threadReplyCounts = [];
+    private int selectedChannelId;
+    private string currentChannelName = string.Empty;
+    private string currentChannelDescription = string.Empty;
+
+    private bool threadOpen;
+    private Message? threadRootMessage;
+    private List<Message> threadReplies = [];
+
+    private bool isLoadingMore;
+    private bool hasMoreMessages = true;
+    private const int PageSize = 30;
+
+    protected override async Task OnInitializedAsync()
+    {
+        channels = await ChatService.GetChannelsAsync();
+        if (channels.Count > 0)
+        {
+            await SelectChannel(channels[0].Id);
+        }
+    }
+
+    private async Task SelectChannel(int channelId)
+    {
+        selectedChannelId = channelId;
+        var channel = channels.First(c => c.Id == channelId);
+        currentChannelName = channel.Name;
+        currentChannelDescription = channel.Description;
+
+        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
+        hasMoreMessages = messages.Count == PageSize;
+        threadReplyCounts = await BuildThreadReplyCounts();
+
+        await ChatService.MarkChannelReadAsync(channelId);
+
+        // Update local unread count
+        var idx = channels.FindIndex(c => c.Id == channelId);
+        if (idx >= 0)
+        {
+            channels[idx] = channels[idx] with { UnreadCount = 0 };
+        }
+
+        CloseThread();
+    }
+
+    private async Task<Dictionary<int, int>> BuildThreadReplyCounts()
+    {
+        var counts = new Dictionary<int, int>();
+        var rootMessages = messages.Where(m => m.ReplyToId is null).ToList();
+        foreach (var root in rootMessages)
+        {
+            var replyCount = messages.Count(m => m.ReplyToId == root.Id);
+            if (replyCount > 0)
+            {
+                counts[root.Id] = replyCount;
+            }
+        }
+        return await Task.FromResult(counts);
+    }
+
+    private async Task LoadMoreMessages()
+    {
+        if (isLoadingMore || !hasMoreMessages) return;
+
+        isLoadingMore = true;
+        StateHasChanged();
+
+        var older = await ChatService.GetMessagesAsync(selectedChannelId, messages.Count, PageSize);
+        hasMoreMessages = older.Count == PageSize;
+
+        messages.InsertRange(0, older);
+        threadReplyCounts = await BuildThreadReplyCounts();
+
+        isLoadingMore = false;
+    }
+
+    private async Task SendMessage(string content)
+    {
+        var sent = await ChatService.SendMessageAsync(selectedChannelId, content, null);
+        messages.Add(sent);
+    }
+
+    private async Task OpenThread(int rootMessageId)
+    {
+        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
+        threadReplies = await ChatService.GetThreadAsync(rootMessageId);
+        threadOpen = true;
+    }
+
+    private void CloseThread()
+    {
+        threadOpen = false;
+        threadRootMessage = null;
+        threadReplies = [];
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (threadRootMessage is null) return;
+        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
+        threadReplies.Add(reply);
+
+        // Update reply count
+        threadReplyCounts[threadRootMessage.Id] =
+            threadReplyCounts.GetValueOrDefault(threadRootMessage.Id) + 1;
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+
+        // Optimistically update local state
+        var msgIdx = messages.FindIndex(m => m.Id == args.MessageId);
+        if (msgIdx >= 0)
+        {
+            var msg = messages[msgIdx];
+            var reactions = msg.Reactions.ToList();
+            var existing = reactions.FindIndex(r => r.Emoji == args.Emoji);
+            if (existing >= 0)
+            {
+                var r = reactions[existing];
+                reactions[existing] = r with { Users = [..r.Users, "You"] };
+            }
+            else
+            {
+                reactions.Add(new Reaction(args.Emoji, ["You"]));
+            }
+            messages[msgIdx] = msg with { Reactions = reactions };
+        }
+    }
+}
